mapper.select:
SELECT VARIABLE, TYPE, DESCRIPTION, REGISTER_USER, REGISTER_DATETIME
FROM hdoc_variables
WHERE 1=1


         AND VARIABLE != #{variable}
         AND VARIABLE > #{variable}
         AND VARIABLE < #{variable}
         AND VARIABLE = #{variable}




         AND TYPE != #{type}
         AND TYPE > #{type}
         AND TYPE < #{type}
         AND TYPE = #{type}




         AND DESCRIPTION != #{description}
         AND DESCRIPTION > #{description}
         AND DESCRIPTION < #{description}
         AND DESCRIPTION = #{description}




         AND REGISTER_USER != #{registerUser}
         AND REGISTER_USER > #{registerUser}
         AND REGISTER_USER < #{registerUser}
         AND REGISTER_USER = #{registerUser}




         AND REGISTER_DATETIME != #{registerDatetime}
         AND REGISTER_DATETIME > #{registerDatetime}
         AND REGISTER_DATETIME < #{registerDatetime}
         AND REGISTER_DATETIME = #{registerDatetime}


ORDER BY VARIABLE
